@startuml

class User {
  + ID : int
  + Name : string
  + Email : string
  + DateOfBirth : date
}

class Account {
  + AccountNumber : int
}

class PersonalAccount extends Account {}

class BusinessAccount extends Account {
  + CompanyName : string
  + MonthlyFee : float
}

class Page {
  + PageName : string
  + NumberOfVisits : int
}

class AdvertisementPage extends Page {
  + BounceRate : float
  + ClickThroughRate : float
  + ConversionRate : float
}

class FriendRequest {}

User "1" -- "1" Account
Account "1" -- "*" Page
PersonalAccount "1" -- "*" FriendRequest
PersonalAccount "1" -- "*" Page : has privileges
BusinessAccount "1" -- "*" AdvertisementPage

@enduml

